// ------------------------------------------------------------------------------
// GENERADOR MAESTRO DE ASEGURAMIENTO (PLUG & PLAY PARA PRODUCCIÓN SUSALUD / SITEDS)
// # TODO: CONECTAR ENDPOINT REAL SITEDS / SUSALUD (Plataforma PIDE del Estado)
// ------------------------------------------------------------------------------
// ------------------------------------------------------------------------------
// GENERADOR DETERMINÍSTICO DE SEED BASADO EN DNI (CERO AZAR ENTRE SESIONES)
// ------------------------------------------------------------------------------
function generarSeedDesdeDni(dni, salt = "") {
  const digits = String(dni).replace(/\D/g, "") + String(salt);
  let hash = 2166136261;
  for (let i = 0; i < digits.length; i++) {
    hash ^= digits.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (Math.abs(hash) % 100000) / 100000;
}

// ------------------------------------------------------------------------------
// CONSTRUCTOR DE PADRÓN SUSALUD A PARTIR DE SEGURO EXISTENTE EN BD HISTÓRICA
// ------------------------------------------------------------------------------
function crearPadronDesdeSeguroExistente(numDni, seguro) {
  const s = String(seguro || "").toLowerCase();
  const rndCode = 1000 + Math.floor(generarSeedDesdeDni(numDni, "code") * 9000);
  const rndSiteds = 10000 + Math.floor(generarSeedDesdeDni(numDni, "siteds") * 90000);

  if (s.includes("sis") || s.includes("minsa")) {
    return {
      dni: numDni,
      tipo_aseguramiento: "SOLO_SIS",
      condicion_evento: "NORMAL",
      publico: { entidad: "SIS", regimen: "SIS Gratuito / Para Todos", estado: "ACTIVO", codigo: `FUA-2026-${rndCode}` },
      privado: { iafas_eps: "SIN COBERTURA PRIVADA (AFILIADO SIS)", estado_poliza: "INACTIVA", copago_fijo: 0, coaseguro_pct: 1.0, exclusiones: [] },
      origen_registro: "BD_HISTORICA"
    };
  } else if (s.includes("essalud")) {
    return {
      dni: numDni,
      tipo_aseguramiento: "SOLO_ESSALUD",
      condicion_evento: "NORMAL",
      publico: { entidad: "ESSALUD", regimen: "EsSalud Regular Titular", estado: "ACTIVO", codigo: `AUT-ESS-${rndCode}` },
      privado: { iafas_eps: "SIN COBERTURA EPS (SOLO ESSALUD)", estado_poliza: "INACTIVA", copago_fijo: 0, coaseguro_pct: 1.0, exclusiones: [] },
      origen_registro: "BD_HISTORICA"
    };
  } else if (s.includes("eps") || s.includes("pacifico") || s.includes("rimac") || s.includes("mapfre") || s.includes("sanitas")) {
    const iafas = s.includes("rimac") ? "Rímac EPS" : s.includes("mapfre") ? "Mapfre EPS" : s.includes("sanitas") ? "Sanitas Perú" : "Pacífico EPS";
    return {
      dni: numDni,
      tipo_aseguramiento: "EPS_Y_ESSALUD",
      condicion_evento: "NORMAL",
      publico: { entidad: "ESSALUD", regimen: "EsSalud Activo (Vínculo Laboral EPS)", estado: "ACTIVO", codigo: `AUT-ESS-${rndCode}` },
      privado: { siteds_codigo: `SITEDS-2026-${rndSiteds}`, iafas_eps: iafas, plan_salud: "Plan Red Preferente", estado_poliza: "ACTIVA", copago_fijo: /sanitas/i.test(s) ? 35 : /mapfre/i.test(s) ? 40 : /pac[ií]fico/i.test(s) ? 50 : 60, coaseguro_pct: /sanitas/i.test(s) ? 0.10 : /rimac/i.test(s) ? 0.15 : 0.20, exclusiones: [] },
      origen_registro: "BD_HISTORICA"
    };
  } else if (s.includes("privad")) {
    return {
      dni: numDni,
      tipo_aseguramiento: "SOLO_PRIVADO",
      condicion_evento: "NORMAL",
      publico: { entidad: "NINGUNA (TIENE SEGURO PRIVADO)", regimen: "No Acreditado en Estado", estado: "INACTIVO", codigo: null },
      privado: { siteds_codigo: `SITEDS-2026-${rndSiteds}`, iafas_eps: "Pacífico Seguros (Individual)", plan_salud: "Plan Individual Preferente", estado_poliza: "ACTIVA", copago_fijo: 80.00, coaseguro_pct: 0.20, exclusiones: [] },
      origen_registro: "BD_HISTORICA"
    };
  } else if (s.includes("sin seguro") || s.includes("particular")) {
    return {
      dni: numDni,
      tipo_aseguramiento: "SOLO_PRIVADO",
      condicion_evento: "NORMAL",
      publico: { entidad: "NINGUNA", regimen: "Particular No Afiliado", estado: "INACTIVO", codigo: null },
      privado: { iafas_eps: "PARTICULAR (SIN SEGURO)", plan_salud: "Tarifario General Particular 100%", estado_poliza: "INACTIVA", copago_fijo: 0, coaseguro_pct: 1.0, exclusiones: [] },
      origen_registro: "BD_HISTORICA"
    };
  } else {
    return {
      dni: numDni,
      tipo_aseguramiento: "SIN_SEGURO",
      condicion_evento: "NORMAL",
      publico: { entidad: "NINGUNA", regimen: "PARTICULAR NO ASEGURADO", estado: "INACTIVO", codigo: null },
      privado: { iafas_eps: "PARTICULAR (SIN SEGURO)", estado_poliza: "INACTIVA", copago_fijo: 0, coaseguro_pct: 1.0, exclusiones: [] },
      origen_registro: "BD_HISTORICA"
    };
  }
}

// ------------------------------------------------------------------------------
// GUARDADO CONSOLIDADO EN TODOS LOS ALMACENAMIENTOS PARA EVITAR MUTACIONES
// ------------------------------------------------------------------------------
function guardarPadronEnTodosLosStorages(numDni, padron, seguroTexto) {
  if (!numDni || !padron) return;
  const seguroEntrada = seguroTexto || (padron.tipo_aseguramiento === "SOLO_SIS" ? "SIS" :
    padron.tipo_aseguramiento === "SOLO_ESSALUD" ? "EsSalud" :
    padron.tipo_aseguramiento === "EPS_Y_ESSALUD" || padron.tipo_aseguramiento === "SOLO_PRIVADO"
      ? (padron.privado?.iafas_eps || "Seguro Privado") : "Particular");
  let seguroGuardado = localStorage.getItem("seguro_asignado_" + numDni);
  let padronGuardado = null;
  try {
    const rawActual = localStorage.getItem("padron_susalud_" + numDni);
    padronGuardado = rawActual ? JSON.parse(rawActual) : null;
  } catch (e) {}
  if (padronGuardado && padronGuardado.tipo_aseguramiento === padron.tipo_aseguramiento) padron = padronGuardado;
  const sTextoDerivado = (seguroGuardado && seguroGuardado !== "Seguro por confirmar" && seguroGuardado !== "Pendiente de Acreditación") ? seguroGuardado : (padron.tipo_aseguramiento === "SOLO_SIS" ? "SIS" :
                 padron.tipo_aseguramiento === "SOLO_ESSALUD" ? "EsSalud" :
                 padron.tipo_aseguramiento === "EPS_Y_ESSALUD" ? (padron.privado?.iafas_eps || "Pacífico EPS") :
                 padron.tipo_aseguramiento === "SOLO_PRIVADO" ? (padron.privado?.iafas_eps || "Seguro Privado") : "Particular");
  if (!seguroGuardado) {
    try {
      const master = typeof cargarPacientesMaster === "function" ? cargarPacientesMaster() : {};
      seguroGuardado = master[numDni]?.tipo_seguro || Object.values(master).find(p => String(p.identificador || "").includes(numDni))?.tipo_seguro || "";
    } catch (e) {}
  }
  const sTexto = (seguroGuardado && seguroGuardado !== "Seguro por confirmar" && seguroGuardado !== "Pendiente de Acreditación") ? seguroGuardado : sTextoDerivado;
  if (!seguroGuardado || seguroGuardado === "Seguro por confirmar" || seguroGuardado === "Pendiente de Acreditación") {
    try { localStorage.setItem("seguro_asignado_" + numDni, seguroEntrada); } catch(e) {}
  }
  if (padronGuardado && seguroGuardado && seguroGuardado !== "Seguro por confirmar" && seguroGuardado !== "Pendiente de Acreditación") {
    const norm = s => String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
    if (norm(seguroEntrada) !== norm(seguroGuardado)) {
      try { padron = crearPadronDesdeSeguroExistente(numDni, seguroGuardado); } catch(e) {}
    }
  }
  try {
    localStorage.setItem("padron_susalud_" + numDni, JSON.stringify(padron));
    localStorage.setItem("seguro_asignado_" + numDni, sTexto);
    let rawBD = localStorage.getItem("PADRON_UNICO_SUSALUD_BD");
    let bd = rawBD ? JSON.parse(rawBD) : {};
    bd[numDni] = padron;
    localStorage.setItem("PADRON_UNICO_SUSALUD_BD", JSON.stringify(bd));
  } catch(e){}

  if (typeof guardarSeguroPacienteEnBd === "function" && !seguroGuardado) {
    try { guardarSeguroPacienteEnBd(numDni, STATE?.historiaClinica || `HC-2026-${numDni.slice(-4)}`, STATE?.nombreReniec || numDni, sTexto); } catch(e){}
  }

  if (typeof cargarPacientesMaster === "function") {
    try {
      const master = cargarPacientesMaster();
      const keyMaster = master[numDni] ? numDni : Object.keys(master).find(k => String(master[k]?.identificador || "").includes(numDni));
      if (keyMaster && master[keyMaster]) {
        if (!master[keyMaster].tipo_seguro || master[keyMaster].tipo_seguro === "Seguro por confirmar" || master[keyMaster].tipo_seguro === "Pendiente de Acreditación") master[keyMaster].tipo_seguro = sTexto;
        master[keyMaster].padron_susalud = padron;
        if (typeof guardarPacientesMaster === "function") guardarPacientesMaster(master);
      }
    } catch(e){}
  }

  // Sincronizar en expedientesStore si el paciente está en la cola o historial
  try {
    if (typeof expedientesStore !== 'undefined' && expedientesStore.actualizarPaciente) {
      const todos = expedientesStore.obtenerExpedientes ? expedientesStore.obtenerExpedientes() : [];
      const pxEnc = todos.find(p => String(p.dni || p.identificador || "").replace(/\D/g, "") === numDni);
      if (pxEnc) {
        expedientesStore.actualizarPaciente(pxEnc.id || pxEnc.hc, {
          seguro: sTexto,
          tipoSeguro: sTexto,
          padronSusalud: padron
        });
      }
    }
  } catch(e){}

  // Sincronizar en STATE si corresponde al paciente actual en atención
  if (typeof STATE !== 'undefined' && STATE) {
    const actDni = String(STATE.numDni || STATE.identificador || "").replace(/\D/g, "");
    if (actDni === numDni) {
      STATE.tipoSeguro = sTexto;
      STATE.padronSusalud = padron;
      if (STATE.pacienteActual) {
        STATE.pacienteActual.seguro = sTexto;
        STATE.pacienteActual.tipoSeguro = sTexto;
        STATE.pacienteActual.padronSusalud = padron;
      }
    }
  }

  if (SUPABASE_CONFIG.url && SUPABASE_CONFIG.key) {
    try {
      fetch(`${SUPABASE_CONFIG.url}/rest/v1/historias_clinicas?identificador=eq.${numDni}`, {
        method: "PATCH",
        headers: { "apikey": SUPABASE_CONFIG.key, "Authorization": `Bearer ${SUPABASE_CONFIG.key}`, "Content-Type": "application/json" },
      body: JSON.stringify({ padron_susalud: padron, tipo_seguro: seguroGuardado || sTexto })
      }).catch(() => {});
    } catch(e){}
  }
}

